{-| @Backend.Runtime.Host.Input — line reads with stream-owned decoder state
    and the byte-sequence rules shared by host text input. -}
module Pudu.Backend.Runtime.Host.Input (hostInputParts) where

import Data.Text (Text)

hostInputParts :: [(Text, [Text], [Text])]
hostInputParts =
  [ ("host_text_input", ["host_fail_io"],
      [ "static size_t pudu_host_text_width(unsigned char lead, unsigned char *low, unsigned char *high) {"
      , "  *low = lead == 0xE0 ? 0xA0 : lead == 0xF0 ? 0x90 : 0x80;"
      , "  *high = lead == 0xED ? 0x9F : lead == 0xF4 ? 0x8F : 0xBF;"
      , "  if (lead < 0x80) return 1;"
      , "  if (lead >= 0xC2 && lead <= 0xDF) return 2;"
      , "  if (lead >= 0xE0 && lead <= 0xEF) return 3;"
      , "  if (lead >= 0xF0 && lead <= 0xF4) return 4;"
      , "  return 0;"
      , "}"
      , "static void pudu_host_fail_text_byte(pudu_text source, const char *operation, int invalid) {"
      , "  char reason[64];"
      , "  snprintf(reason, sizeof reason, \"cannot decode byte sequence starting from %u\", (unsigned)invalid);"
      , "  pudu_host_fail_reason(source, operation, \"invalid argument\", reason);"
      , "}"
      ])
  , ("host_read_line", ["host_text_input", "host_done", "host_gate", "text_copy"],
      [ "#include <errno.h>"
      , "#include <poll.h>"
      , "static int pudu_host_line_byte(int *code) {"
      , "  for (;;) {"
      , "    errno = 0;"
      , "    int byte = getc_unlocked(stdin);"
      , "    if (byte != EOF) return byte;"
      , "    *code = ferror(stdin) ? (errno == 0 ? EIO : errno) : 0;"
      , "    clearerr(stdin);"
      , "    if (*code == EAGAIN || *code == EWOULDBLOCK) {"
      , "      struct pollfd waiting = {fileno(stdin), POLLIN, 0};"
      , "      int ready;"
      , "      if (waiting.fd < 0) { *code = errno; return EOF; }"
      , "      do { ready = poll(&waiting, 1, -1); } while (ready < 0 && errno == EINTR);"
      , "      if (ready < 0) { *code = errno; return EOF; }"
      , "    } else if (*code != EINTR) return EOF;"
      , "    *code = 0;"
      , "  }"
      , "}"
      , "static pudu_text pudu_host_read_line(void) {"
      , "  static int invalid = -1;"
      , "  pudu_text source = {(const unsigned char *)\"<stdin>\", 7, NULL};"
      , "  pudu_text result = {(const unsigned char *)\"\", 0, NULL};"
      , "  char *line = NULL;"
      , "  size_t length = 0, capacity = 0, needed = 0;"
      , "  unsigned char low = 0x80, high = 0xBF;"
      , "  int byte, lead = 0, ended = 0, bad, code = 0;"
      , "  /* Keep the stream and its decoder state together while the run gate is free. */"
      , "  pudu_host_leave();"
      , "  flockfile(stdin);"
      , "  while (invalid < 0) {"
      , "    byte = pudu_host_line_byte(&code);"
      , "    if (byte == EOF) {"
      , "      if (code == 0 && needed != 0) invalid = lead;"
      , "      ended = length == 0;"
      , "      break;"
      , "    }"
      , "    if (needed != 0) {"
      , "      if (byte < low || byte > high) { invalid = lead; break; }"
      , "      needed -= 1; low = 0x80; high = 0xBF;"
      , "    } else {"
      , "      if (byte == '\\n') break;"
      , "      size_t width = pudu_host_text_width((unsigned char)byte, &low, &high);"
      , "      if (width == 0) { invalid = byte; break; }"
      , "      lead = byte; needed = width - 1;"
      , "    }"
      , "    if (length == capacity) {"
      , "      if (capacity > SIZE_MAX / 2) { code = ENOMEM; break; }"
      , "      capacity = capacity == 0 ? 128 : capacity * 2;"
      , "      char *grown = realloc(line, capacity);"
      , "      if (grown == NULL) { code = ENOMEM; break; }"
      , "      line = grown;"
      , "    }"
      , "    line[length++] = (char)byte;"
      , "  }"
      , "  bad = invalid;"
      , "  funlockfile(stdin);"
      , "  pudu_host_enter();"
      , "  if (bad >= 0) {"
      , "    pudu_host_fail_text_byte(source, \"hGetLine\", bad);"
      , "  } else if (code != 0) {"
      , "    if (code == ENOMEM) { free(line); pudu_memory_failure(); }"
      , "    pudu_host_fail_io(source, length == 0 ? \"hIsEOF\" : \"hGetLine\", code);"
      , "  } else if (ended) {"
      , "    pudu_host_done(2);"
      , "  } else {"
      , "    result = pudu_text_copy(line == NULL ? \"\" : line, length);"
      , "    pudu_host_done(0);"
      , "  }"
      , "  free(line);"
      , "  return result;"
      , "}"
      ])
  ]
